# -*- coding: utf-8 -*-
ICO_B64 = ""

import sys
import tkinter as tk
from tkinter import messagebox
from datetime import date
import base64, io


# ── 고해상도(HiDPI) 모니터 대응 ────────────────────────────────────
#   모니터를 바꾼 뒤 글자가 뿌옇게 번지는 현상은 프로세스가 DPI 인식을
#   하지 않아 Windows가 저해상도 화면을 강제 확대하기 때문이다.
#   Tk 생성 전에 DPI 인식을 켜면 원래 해상도로 선명하게 렌더링된다.

def enable_hidpi():
    """프로세스를 per-monitor DPI 인식으로 설정하고 96DPI 기준 배율을 돌려준다."""
    if not sys.platform.startswith("win"):
        return 1.0
    import ctypes
    try:
        ctypes.windll.user32.SetProcessDpiAwarenessContext(-4)  # PER_MONITOR_AWARE_V2
    except Exception:
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)      # PER_MONITOR_AWARE
        except Exception:
            try:
                ctypes.windll.user32.SetProcessDPIAware()
            except Exception:
                pass
    try:
        return max(1.0, ctypes.windll.user32.GetDpiForSystem() / 96.0)
    except Exception:
        return 1.0

# ── 계산 로직 ─────────────────────────────────────────────────────

def elapsed_months(start, today):
    if today < start: return 0
    y = today.year - start.year
    m = today.month - start.month
    if today.day < start.day: m -= 1
    if m < 0: y -= 1; m += 12
    return y * 12 + m

def remaining_balance(p, rate, n, paid):
    r = rate / 12
    if paid <= 0: return p
    if paid >= n: return 0.0
    M = p * r * (1+r)**n / ((1+r)**n - 1)
    for _ in range(paid):
        p -= (M - p * r)
    return p

def calc_mortgage(amount, is_loan, recv=None, today=None):
    if today is None: today = date.today()
    res = {"채권최고액": amount, "기준일": today, "접수일자": None, "경과월수": None}
    if is_loan:
        p = amount / 150 * 100
        res.update({"구분": "대부/개인", "대출원금": p, "저당액": p,
                    "방식": "대부/개인: 채권최고액÷150×100 (기간계산 없음)"})
        return res
    p = amount / 120 * 100
    res.update({"구분": "은행", "대출원금": p})
    if recv is None: raise ValueError("은행 케이스는 접수일자 필요")
    m = elapsed_months(recv, today)
    res.update({"경과월수": m, "접수일자": recv})
    if m < 1:
        res.update({"저당액": p, "방식": "은행: 채권최고액÷120×100 (접수 1개월 미만, 원금 그대로)"})
    else:
        b = remaining_balance(p, 0.03, 240, m)
        res.update({"저당액": b, "방식": f"은행: 채권최고액÷120×100 → 20년/연3% 원리금균등상환 → {m}개월 경과 잔액"})
    return res

# ── 색상 / 폰트 ───────────────────────────────────────────────────

BG   = "#1C1C1E"   # 앱 배경
BG2  = "#2C2C2E"   # 버튼/입력 배경
BG3  = "#3A3A3C"   # 비활성 버튼
OR   = "#FF9F0A"   # 오렌지 강조
TXT  = "#FFFFFF"
TXT2 = "#AEAEB2"
TXT3 = "#636366"
TXT4 = "#48484A"

def F(size, bold=False):
    return ("맑은 고딕", size, "bold" if bold else "normal")

# ── 토글 버튼 ─────────────────────────────────────────────────────

class Toggle(tk.Frame):
    def __init__(self, parent, text, active=False, cmd=None):
        super().__init__(parent, bg=OR if active else BG2,
                         highlightthickness=0, cursor="hand2")
        self._cmd = cmd
        self._lbl = tk.Label(self, text=text,
                             font=F(12, True),
                             fg="#000" if active else TXT3,
                             bg=OR if active else BG2,
                             padx=0, pady=10)
        self._lbl.pack(fill="both", expand=True)
        for w in (self, self._lbl):
            w.bind("<ButtonRelease-1>", lambda e: self._cmd() if self._cmd else None)

    def activate(self, on):
        c = OR if on else BG2
        fg = "#000" if on else TXT3
        self.configure(bg=c)
        self._lbl.configure(bg=c, fg=fg)

# ── 입력 필드 헬퍼 ────────────────────────────────────────────────

def make_entry(parent, width=None, justify="right"):
    kw = dict(font=F(13, True), fg=TXT, bg=BG2,
              insertbackground=OR, relief="flat",
              highlightthickness=1,
              highlightbackground=BG3,
              highlightcolor=OR,
              justify=justify)
    if width:
        kw["width"] = width
    e = tk.Entry(parent, **kw)
    e.bind("<FocusIn>",  lambda ev: ev.widget.configure(highlightbackground=OR))
    e.bind("<FocusOut>", lambda ev: ev.widget.configure(highlightbackground=BG3))
    return e

# ── 메인 앱 ──────────────────────────────────────────────────────

class App(tk.Tk):
    def __init__(self, scale: float = 1.0):
        super().__init__()
        self.scale = scale
        # 포인트 폰트 크기가 배율에 맞춰 커지도록 Tk 스케일링 지정 → 선명 유지
        try:
            self.tk.call("tk", "scaling", scale * 96.0 / 72.0)
        except Exception:
            pass
        self.title("저당액 계산기")
        self.configure(bg=BG)
        self.resizable(False, False)
        # 창 크기(픽셀)도 배율만큼 키워야 폰트와 균형이 맞는다
        self.geometry(f"{int(380 * scale)}x{int(680 * scale)}")
        self._set_icon()
        self.creditor = tk.StringVar(value="은행")
        self._res = None
        self._build()

    def _set_icon(self):
        try:
            from PIL import Image, ImageTk
            data = base64.b64decode(ICO_B64)
            im = Image.open(io.BytesIO(data)).resize((32, 32), Image.LANCZOS)
            self._icon = ImageTk.PhotoImage(im)
            self.iconphoto(True, self._icon)
        except Exception:
            pass

    # ── 전체 레이아웃 ─────────────────────────────────────
    def _build(self):
        self.columnconfigure(0, weight=1)
        self.rowconfigure(0, weight=1)   # 디스플레이
        self.rowconfigure(1, weight=0)   # 컨트롤

        self._display()
        self._controls()

    # ── 디스플레이 (상단) ─────────────────────────────────
    def _display(self):
        f = tk.Frame(self, bg=BG)
        f.grid(row=0, column=0, sticky="ew", padx=20, pady=(2, 0))
        f.columnconfigure(0, weight=1)

        # 저당액 라벨
        tk.Label(f, text="저당액", font=F(16, True),
                 fg=TXT, bg=BG, anchor="e").grid(row=0, column=0, sticky="e")

        # 숫자 + 원 (오른쪽 정렬, 잘림 방지)
        num_row = tk.Frame(f, bg=BG)
        num_row.grid(row=1, column=0, sticky="e", pady=(2, 0))
        num_row.columnconfigure(0, weight=1)

        self.num_lbl = tk.Label(num_row, text="0",
                                font=("맑은 고딕", 48, "bold"),
                                fg=TXT, bg=BG, cursor="hand2", anchor="e")
        self.num_lbl.pack(side="left")
        self.won_lbl = tk.Label(num_row, text=" 원", font=F(13),
                 fg=TXT3, bg=BG, anchor="sw")
        self.won_lbl.pack(side="left", pady=(12, 0))
        self.num_lbl.bind("<Button-1>", self._copy)
        num_row.bind("<Button-1>", self._copy)
        self.won_lbl.bind("<Button-1>", self._copy)

        # 복사 안내
        self.copy_hint = tk.Label(f, text="숫자를 클릭하면 복사됩니다",
                                  font=F(8), fg=TXT4, bg=BG, anchor="e")
        self.copy_hint.grid(row=2, column=0, sticky="e", pady=(1, 4))

        # 상세 정보 (각 줄 고정)
        self.lbl_amount = tk.Label(f, text="", font=F(9), fg=TXT, bg=BG, anchor="w")
        self.lbl_princ  = tk.Label(f, text="", font=F(9), fg=TXT, bg=BG, anchor="w")
        self.lbl_date   = tk.Label(f, text="", font=F(9), fg=TXT, bg=BG, anchor="w")
        self.lbl_today  = tk.Label(f, text="", font=F(9), fg=TXT, bg=BG, anchor="w")
        self.lbl_method = tk.Label(f, text="", font=F(9), fg=TXT, bg=BG, anchor="w",
                                   wraplength=int(340 * self.scale), justify="left")
        self.lbl_amount.grid(row=3, column=0, sticky="ew")
        self.lbl_princ.grid( row=4, column=0, sticky="ew")
        self.lbl_date.grid(  row=5, column=0, sticky="ew")
        self.lbl_today.grid( row=6, column=0, sticky="ew")
        self.lbl_method.grid(row=7, column=0, sticky="ew", pady=(2, 6))

        # 구분선
        tk.Frame(self, bg=BG2, height=1).grid(row=0, column=0, sticky="sew")

    # ── 컨트롤 (하단) ─────────────────────────────────────
    def _controls(self):
        f = tk.Frame(self, bg=BG)
        f.grid(row=1, column=0, sticky="ew", padx=20, pady=(10, 14))
        f.columnconfigure((0, 1), weight=1)

        # ① 근저당권자 토글
        self._lbl("근저당권자", f, row=0)
        self.tb_bank = Toggle(f, "은행",     active=True,  cmd=lambda: self._sel("은행"))
        self.tb_loan = Toggle(f, "대부 / 개인", active=False, cmd=lambda: self._sel("대부"))
        self.tb_bank.grid(row=1, column=0, sticky="ew", padx=(0, 5), pady=(4, 8), ipady=0)
        self.tb_loan.grid(row=1, column=1, sticky="ew", padx=(5, 0), pady=(4, 8), ipady=0)

        # ② 채권최고액
        self._lbl("채권최고액 (원)", f, row=2)
        self.amt = make_entry(f)
        self.amt.grid(row=3, column=0, columnspan=2, sticky="ew",
                      pady=(4, 8), ipady=8)

        # ③ 접수일자
        self.dl = self._lbl("접수일자", f, row=4)
        df = tk.Frame(f, bg=BG)
        df.grid(row=5, column=0, columnspan=2, sticky="ew", pady=(4, 8))
        df.columnconfigure((0, 2, 4), weight=1)

        self.ye = make_entry(df, width=6, justify="center")
        self.me = make_entry(df, width=4, justify="center")
        self.de = make_entry(df, width=4, justify="center")
        self.date_ws = [self.ye, self.me, self.de]

        self.ye.grid(row=0, column=0, sticky="ew", ipady=7)
        tk.Label(df, text="년", font=F(11), fg=TXT3, bg=BG).grid(row=0, column=1, padx=6)
        self.me.grid(row=0, column=2, sticky="ew", ipady=7)
        tk.Label(df, text="월", font=F(11), fg=TXT3, bg=BG).grid(row=0, column=3, padx=6)
        self.de.grid(row=0, column=4, sticky="ew", ipady=7)
        self.de.bind("<Return>", lambda e: self._calc())
        tk.Label(df, text="일", font=F(11), fg=TXT3, bg=BG).grid(row=0, column=5, padx=6)

        # ④ 계산 / 초기화 버튼
        btn_row = tk.Frame(f, bg=BG)
        btn_row.grid(row=6, column=0, columnspan=2, sticky="ew", pady=(4, 0))
        btn_row.columnconfigure(0, weight=3)
        btn_row.columnconfigure(1, weight=1)

        calc = tk.Button(btn_row, text="계산",
                         font=F(14, True), fg="#000", bg=OR,
                         activebackground="#E8910A", activeforeground="#000",
                         relief="flat", bd=0, pady=10, cursor="hand2",
                         command=self._calc)
        calc.grid(row=0, column=0, sticky="ew", padx=(0, 6))

        reset = tk.Button(btn_row, text="초기화",
                          font=F(14, True), fg=TXT2, bg=BG2,
                          activebackground=BG3, activeforeground=TXT,
                          relief="flat", bd=0, pady=10, cursor="hand2",
                          command=self._reset)
        reset.grid(row=0, column=1, sticky="ew")

    # ── 헬퍼 ──────────────────────────────────────────────
    def _lbl(self, text, parent, row):
        l = tk.Label(parent, text=text, font=F(10), fg=TXT3, bg=BG, anchor="w")
        l.grid(row=row, column=0, columnspan=2, sticky="w", pady=(0, 0))
        return l

    def _sel(self, val):
        self.creditor.set(val)
        self.tb_bank.activate(val == "은행")
        self.tb_loan.activate(val == "대부")
        is_bank = (val == "은행")
        for w in self.date_ws:
            w.configure(state="normal" if is_bank else "disabled",
                        fg=TXT if is_bank else TXT4)
        self.dl.configure(fg=TXT3 if is_bank else TXT4)

    def _calc(self):
        try:
            raw = self.amt.get().strip().replace(",", "")
            if not raw:
                messagebox.showwarning("입력 오류", "채권최고액을 입력해주세요.")
                return
            amount = float(raw)
            is_loan = (self.creditor.get() == "대부")
            recv = None
            if not is_loan:
                y, m, d = (e.get().strip() for e in self.date_ws)
                if not (y and m and d):
                    messagebox.showwarning("입력 오류", "접수일자를 모두 입력해주세요.")
                    return
                try:    recv = date(int(y), int(m), int(d))
                except: messagebox.showwarning("입력 오류", "올바르지 않은 날짜입니다."); return
            r = calc_mortgage(amount, is_loan, recv)
            self._res = r
            self._show(r)
        except Exception as e:
            messagebox.showerror("오류", str(e))

    def _reset(self):
        """입력값과 결과 표시를 모두 초기 상태로 되돌린다."""
        # 입력 필드 초기화
        self.amt.delete(0, tk.END)
        for w in self.date_ws:
            w.configure(state="normal")
            w.delete(0, tk.END)

        # 근저당권자 토글을 기본값(은행)으로 복귀
        self._sel("은행")

        # 결과 및 디스플레이 초기화
        self._res = None
        self.num_lbl.configure(text="0", fg=TXT, font=("맑은 고딕", 48, "bold"))
        self.won_lbl.configure(font=F(13))
        self.copy_hint.configure(text="숫자를 클릭하면 복사됩니다", fg=TXT4)
        self.lbl_amount.configure(text="")
        self.lbl_princ.configure(text="")
        self.lbl_date.configure(text="")
        self.lbl_today.configure(text="")
        self.lbl_method.configure(text="")

        # 포커스를 채권최고액 입력란으로 이동
        self.amt.focus_set()

    def _auto_font(self, text):
        """숫자+원 합산 너비가 창에 맞는 폰트 크기 탐색"""
        max_width = int(340 * self.scale)
        for size in [44, 38, 32, 27, 22, 18]:
            self.num_lbl.configure(font=("맑은 고딕", size, "bold"), text=text)
            self.won_lbl.configure(font=F(max(9, size - 14)))
            self.num_lbl.update_idletasks()
            self.won_lbl.update_idletasks()
            total = self.num_lbl.winfo_reqwidth() + self.won_lbl.winfo_reqwidth()
            if total <= max_width:
                return size
        return 16

    def _show(self, r):
        num_text = f"{r['저당액']:,.0f}"
        # 폰트 자동 조정 (실제 너비 측정)
        self._auto_font(num_text)
        self.lbl_amount.configure(text=f"채권최고액  :  {r['채권최고액']:,.0f} 원")
        self.lbl_princ.configure( text=f"대출원금    :  {r['대출원금']:,.0f} 원")
        if r.get("접수일자"):
            self.lbl_date.configure(text=f"접수일자    :  {r['접수일자']}  ({r['경과월수']}개월 경과)")
        else:
            self.lbl_date.configure(text="접수일자    :  —")
        self.lbl_today.configure(text=f"기준일      :  {r['기준일']}")
        self.lbl_method.configure(text=f"{r['방식']}")

    def _copy(self, e=None):
        if not self._res: return
        self.clipboard_clear()
        self.clipboard_append(f"{self._res['저당액']:,.0f}")
        # 숫자 색상으로 복사 완료 피드백
        self.num_lbl.configure(fg=OR)
        self.copy_hint.configure(text="✔ 복사됨", fg=OR)
        self.after(1500, lambda: [
            self.num_lbl.configure(fg=TXT),
            self.copy_hint.configure(text="숫자를 클릭하면 복사됩니다", fg=TXT4)
        ])


if __name__ == "__main__":
    scale = enable_hidpi()   # DPI 인식 활성화 (Tk 생성 전에 호출)
    App(scale).mainloop()